from collections import OrderedDict


class LRUCache:
    """Fixed-capacity cache that evicts the least recently used entry."""

    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key, default=None):
        if key not in self._data:
            return default
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __contains__(self, key):
        return key in self._data

    def __len__(self):
        return len(self._data)

    def __repr__(self):
        return "LRUCache(capacity={}, size={})".format(
            self.capacity, len(self._data)
        )
```

`get` and `put` both refresh recency via `move_to_end`; when `put` pushes size past `capacity`, `popitem(last=False)` drops the oldest entry. This is standalone code shown in chat — the repo already has several similarly-named LRU files (`lru_cache.py`, `lru.py`, `simple_lru.py`, `small_lru.py`), so I didn't write to any of them. Let me know if you want this saved to a specific file.
